Function.Code:
global StringArray

set tmp1 [ array exists StringArray ]
if { $tmp1 == 0 } {
   set mke_string_result NO_VALUE
} else {
   set lst [ array get StringArray $mke_StringVariableName ]
   set len [ llength $lst ]
   if { $len == 0 } {
      set mke_string_result NO_VALUE
   } else {
      set mke_string_result [ lindex $lst 1 ] 
   }
}

# 
proc READ_FILE {input} {

    set fileid_intern [open $input r]
    set filecontent [read $fileid_intern]

    close $fileid_intern

    set filecontent [split $filecontent "\n"]
    # return a proper tcl list
    return $filecontent
}

proc CLEAN_LIST {classname raw_list} {

    # clean up the raw_list. There can be empty lines and comment lines

    set clean_list ""
    set class_found 0
    set format_found 0
    foreach e $raw_list {
        if { [string toupper [string trim [lindex $e 0] ] ] == "#"} {
            continue
        }
        if {[regexp -nocase -- "$classname" $e]} {
            set class_found 1
        }
        if {$class_found == 0} {continue}

        # check, if "FORMAT" is at the beginning of the line
        if { [string toupper [string trim [lindex $e 0] ] ] == "FORMAT"} {
            if {$format_found == 1} {break}
            set format_found 1
            lappend clean_list $e
            continue
        }
        if { [string toupper [string trim [lindex $e 0] ] ] == "DATA"} {
            lappend clean_list $e
            continue
        }
    }    
    # give back the list
    return $clean_list
}

proc EQ_is_equal {s t {tol 0}} {

      global mom_system_tolerance

      if {$tol == 0} {set tol 0.0001} ;# Tolerance Default

      if { abs([expr ($s - $t)]) <= abs($tol) } { return 1 } else { return 0 }
}

proc EQ_is_gt {s t {tol 0}} {

      global mom_system_tolerance

      if {$tol == 0} {set tol 0.0001} ;# Tolerance Default

      if { $s > [expr ($t + abs($tol))] } { return 1 } else { return 0 }
}

proc READ_PARAMETER_INDEX {liste parameter} {

    set index [lsearch [ lindex $liste 0 ] $parameter]

    return $index

}

proc SEARCH_TOOL_PARAMETER {searchvariable searchlist} {

    global tool
    global position

    set results ""
    foreach e $searchlist {
    # search for the search variable
    #  when something found the result is > 1
        set dummy_liste [split $e "|"]

        if {[EQ_is_gt [string trim [lindex $dummy_liste $position(dia)]] $searchvariable]} {    
      # create a temp list with a split on the | symbol

            set tool(HEI)    [string trim [lindex $dummy_liste $position(hei)]]
            set tool(FLEN)    [string trim [lindex $dummy_liste $position(flen)]]
            set tool(DESCR)    [string trim [lindex $dummy_liste $position(descr)]]
            set tool(LIBRF)    [string trim [lindex $dummy_liste $position(librf)]]
            set tool(DIA)    [string trim [lindex $dummy_liste $position(dia)]]

            # when the tool is found
            # we can leave the foreach loop with a break
            lappend results "$tool(DIA),$tool(HEI),$tool(LIBRF),$searchvariable"

        }    
    }
#    set sortet_results [lsort -dictionary $results]
    set sortet_results [lsort -real -index 0 $results]
    set smallest_tool [lindex $sortet_results 0]
    set tmp [split $smallest_tool ","]
    set libref [lindex $tmp 2]

    return $libref
}

# Main program
    global tool
    global position
    global mke_part_units    

    set filename ""
    set filepath [MOM_ask_env_var "UGII_CAM_LIBRARY_TOOL_METRIC_DIR"]
    if {$mke_part_units == "metric"} then {set filepath [MOM_ask_env_var "UGII_CAM_LIBRARY_TOOL_METRIC_DIR"]}
    if {$mke_part_units == "english"} then {set filepath [MOM_ask_env_var "UGII_CAM_LIBRARY_TOOL_ENGLISH_DIR"]}
# join together elements to form a file path
    set filename [file join $filepath "tool_database.dat"]

    set input_file [READ_FILE $filename]
    set input_file [CLEAN_LIST $mke_ToolClass $input_file]

    set position(librf) [READ_PARAMETER_INDEX $input_file "LIBRF"]
    set position(hei)     [READ_PARAMETER_INDEX $input_file "HEI"]
    set position(flen)    [READ_PARAMETER_INDEX $input_file "FLEN"]
    set position(descr)    [READ_PARAMETER_INDEX $input_file "DESCR"]
    set position(dia)    [READ_PARAMETER_INDEX $input_file "DIA"]    

    set tool(LIBRF) ""
    set tool(HEI)    ""
    set tool(FLEN)    ""
    set tool(DESCR)    ""
    set tool(DIA) $mke_Value

    set libref_ges_tool [SEARCH_TOOL_PARAMETER $tool(DIA) $input_file]

  set mke_string_result $libref_ges_tool

# Example only. This function may or may not be used in the example machining rules

# Note this is metric only

set mke_double_result 0.1
if {$mke_Diameter > 1} {set mke_double_result 0.9}
if {$mke_Diameter > 3} {set mke_double_result 2.0}
if {$mke_Diameter > 6} {set mke_double_result 4.0}
if {$mke_Diameter > 10} {set mke_double_result 5.0}

# Example only. This function may or may not be used in the example machining rules
global mke_part_units

set mke_double_result 0
# case metric

if {$mke_part_units == "metric"}  {

if {$mke_Diameter >  1} {set mke_double_result 0.2}
if {$mke_Diameter >  3} {set mke_double_result 0.3}
if {$mke_Diameter >  6} {set mke_double_result 0.4}
if {$mke_Diameter > 10} {set mke_double_result 0.5}
if {$mke_Diameter > 18} {set mke_double_result 0.5}
if {$mke_Diameter > 30} {set mke_double_result 0.7}
}

# case inch

if {$mke_part_units == "english"}  {

if {$mke_Diameter >  [expr 1 * 0.04]} {set mke_double_result [expr 0.2 * 0.04]}
if {$mke_Diameter >  [expr 3 * 0.04]} {set mke_double_result [expr 0.3 * 0.04]}
if {$mke_Diameter >  [expr 6 * 0.04]} {set mke_double_result [expr 0.4 * 0.04]}
if {$mke_Diameter > [expr 10 * 0.04]} {set mke_double_result [expr 0.5 * 0.04]}
if {$mke_Diameter > [expr 18 * 0.04]} {set mke_double_result [expr 0.5 * 0.04]}
if {$mke_Diameter > [expr 30 * 0.04]} {set mke_double_result [expr 0.7 * 0.04]}
}

# Example only. This function may or may not be used in the example machining rules

# Note this is metric only

set mke_double_result 1
if {$mke_Diameter >  1} {set mke_double_result 0.1}
if {$mke_Diameter >  3} {set mke_double_result 0.2}
if {$mke_Diameter >  6} {set mke_double_result 0.2}
if {$mke_Diameter > 10} {set mke_double_result 0.2}
if {$mke_Diameter > 18} {set mke_double_result 0.3}
if {$mke_Diameter > 30} {set mke_double_result 0.3}

# Example only. This function may or may not be used in the example machining rules
# Return the 1st next lower pre dill diameter for a specific Hole Diameter that has to be milled.

# Note this is metric only

set dia_list [list 0.8 1 1.2 1.5 1.8 2 2.5 3 4 4.5 5 6 8 10 12 14 16]
set mke_double_result 0
for {set i 0} {$i < [llength $dia_list]} {incr i}\
{
  set val [lindex $dia_list $i]
  if {$val < $mke_Diameter} \
  {
    set mke_double_result $val
  } \
  else \
  {
    set i [llength $dia_list]
  }
}
# MOM_output_to_listing_device "Predrill Diameter Found = $mke_double_result"

# Testing

global mke_part_units
global mke_part_name

# MOM_ask_part_units  ;# writes to mke_part_units

# MOM_output_to_listing_device "Output of TestAskPartUnits TCL function: $mke_part_units"

# MOM_output_to_listing_device "Output of TestAskPartNameTCL function: $mke_part_name"

if {$mke_part_units == "metric"} {
    set mke_string_result "mm"
} elseif {$mke_part_units == "english"} {
    set mke_string_result "inch"
} else {
    set mke_string_result "unknown"
}

MachiningRule.comment:
NX CAM has no surface DEPTH recognition. The DEPTH value is always 0.
There is a possibility to improve this by using the attached KF post recognition function.

Use Tools -> Knowledge Fusion -> DFA Manager.
Then add the directory where you have put the .dfa file.
Copy the text below and paste into the .dfa file.

#! UG/KF 19.0
###############################################################################
Defun: ug_fbm_postCreateFeaturesCustomFunction( Instance $instance )
@{
  # Get the features to process
  $list_features << ug_fbm_askPostCreateFeatures();

  printValue( "Number of input features> " + StringValue( length( $list_features ) ) );

  $result << if ( length( $list_features ) > 0 ) then
    Loop
    {
      # Process all features
      for $feature in $list_features;

      do if ( Substring(ug_fbm_askFeatureName( $feature ),1,7) = "SURFACE" ) then
      @{
         printValue( "Feature name> " + ug_fbm_askFeatureName( $feature ) );

         # Get and set the feature top stock
         $top_stock << ug_fbm_askFeatureTopStock( $feature );
         printValue( "Top stock> " + StringValue( $top_stock ) );

         if ( $top_stock > 0.0 ) then 
         @{
            ug_fbm_deleteFeatureAttribute($feature, "DEPTH");
            ug_fbm_AddfeatureAttribute( $feature, "DEPTH", $top_stock );
         } else false;
      } else false;
      return is true;
    }
  else false;

  $result;
} Boolean;

NX CAM has no surface DEPTH recognition. The DEPTH value is always 0.
There is a possibility to improve this by using the attached KF post recognition function.
It adds an extra TOP_STOCK attribute to the recognized features.

Use Tools -> Knowledge Fusion -> DFA Manager.
